def _clean_summary_text(raw_text, fallback_title):
    if not raw_text:
        return f"Hands-on video overview of {fallback_title} covering key specifications, sizing, and daily usability."
    notes = re.sub(r"https?://\S+", "", raw_text)
    notes = re.sub(r"Product link:\s*🔗?\s*Check it out:\s*", "", notes, flags=re.I)
    notes = re.sub(r"Link to Buy\s*-\s*", "", notes, flags=re.I)
    notes = re.sub(r"🔗\s*Check it out:\s*", "", notes, flags=re.I)
    notes = re.sub(r"Disclosure:.*?(?:cost to you\.|purchases\.|link\.)", "", notes, flags=re.I)
    notes = re.sub(r"As an Amazon Associate[^\.]*\.", "", notes, flags=re.I)
    notes = re.sub(r"This helps support the channel at no extra cost to you\.", "", notes, flags=re.I)
    notes = re.sub(r"#\w+", "", notes)
    notes = re.sub(r"\s{2,}", " ", notes).strip(" -—•:")
    return notes[:550] if len(notes) > 30 else f"Hands-on video overview of {fallback_title} covering key specifications, sizing, and daily usability."


def _fetch_xml_feed_lookup():
    import xml.etree.ElementTree as ET
    lookup = {}
    yt_cids = [
        "UCdcte1tNyB_F6a4P9S1V7dw",
        "UCJuQdlTl_DE_7E4TbgcXUtQ",
        "UCizMutB0xtYKPsXGUQDfy-Q",
        "UC8dMCVIMDD--MPY1Bwe_OKQ",
    ]
    ns = {
        "atom": "http://www.w3.org/2005/Atom",
        "yt": "http://www.youtube.com/xml/schemas/2015",
        "media": "http://search.yahoo.com/mrss/",
    }
    for cid in yt_cids:
        try:
            r = requests.get(f"https://www.youtube.com/feeds/videos.xml?channel_id={cid}", timeout=10)
            if r.status_code == 200 and "<feed" in r.text:
                root = ET.fromstring(r.text)
                for entry in root.findall("atom:entry", ns):
                    vid_el = entry.find("yt:videoId", ns)
                    desc_el = entry.find("media:group/media:description", ns)
                    if vid_el is not None and vid_el.text and desc_el is not None and desc_el.text:
                        lookup[vid_el.text.strip()] = desc_el.text
        except Exception:
            pass
    return lookup


def _enrich_one_real_video(v):
    """Pulls the exact Amazon product link (e.g. amazon.com/dp/...?tag=ziolek-20
    or amzn.to/...) and full product description via YouTube's official JSON API!"""
    if v.get("amazon_url") and ("/dp/" in v["amazon_url"] or "amzn.to" in v["amazon_url"]) and v.get("yt_description") and "..." not in v["amazon_url"]:
        return v
    vid = v.get("video_id", "")
    if not vid:
        return v
    try:
        import urllib.parse
        payload = {
            "context": {
                "client": {
                    "clientName": "WEB",
                    "clientVersion": "2.20261015.01.00",
                    "hl": "en",
                    "gl": "US",
                }
            },
            "videoId": vid,
        }
        r = requests.post("https://www.youtube.com/youtubei/v1/next?prettyPrint=false", json=payload, timeout=10)
        raw_desc = ""
        m = re.search(r'"attributedDescriptionBodyText":\{"content":"((?:\\.|[^"\\])*)"', r.text)
        if m:
            raw_desc = json.loads('"' + m.group(1) + '"')
        amz_url = ""
        for qm in re.finditer(r'q=(https?%3A%2F%2F[^&"\\]+)', r.text):
            u = urllib.parse.unquote(qm.group(1))
            if "amazon." in u or "amzn.to" in u or "a.co" in u:
                amz_url = u
                break
        if not amz_url and raw_desc:
            am = re.search(
                r"(https?://(?:www\.)?(?:amzn\.to|a\.co|amazon\.[a-z\.]+)/[^\s\)\"\]]+)",
                raw_desc,
                re.I,
            )
            if am:
                amz_url = am.group(1)
        if amz_url and amz_url.endswith("?..."):
            amz_url = amz_url.replace("?...", f"?tag={CONFIG['amazon_tag']}")
        if amz_url:
            v["amazon_url"] = amz_url
            if raw_desc:
                raw_desc = re.sub(r"https?://(?:www\.)?amazon\.[a-z\.]+/dp/[A-Z0-9]{10}\?\.\.\.", amz_url, raw_desc)
        if raw_desc:
            v["yt_description"] = re.sub(r"\s{2,}", " ", raw_desc).strip()[:1400]
            v["transcript_summary"] = _clean_summary_text(raw_desc, v.get("title", "Product Review"))
    except Exception:
        pass
    return v


def load_videos_from_library(fallback_videos):
    """Automatically loads ONLY your real videos from your 4 YouTube channels
    inside videos_library.json, removes any initial demo videos, and extracts
    the exact Amazon link & description (with Amazon link included!) from each video!"""
    demo_ids = {"IBVmenOroPs", "dQw4w9WgXcQ", "ysz5S6PUM-U", "aqz-KE-bpKQ"}
    ch_names = {
        "ch1": "KitchenGear",
        "ch2": "Simple Home Reviews",
        "ch3": "Bedroom Comfort",
        "ch4": "WorldShoping",
    }
    if os.path.exists("videos_library.json"):
        try:
            with open("videos_library.json", "r", encoding="utf-8") as f:
                lib = json.load(f)
            if isinstance(lib, list) and len(lib) > 0:
                real_only = [
                    v for v in lib
                    if "•" not in v.get("channel_name", "")
                    and v.get("video_id") not in demo_ids
                ]
                if real_only:
                    # 0. Merge any pre-enriched videos from PRE_ENRICHED_LOOKUP not yet in videos_library.json
                    existing_ids = {v.get("video_id") for v in real_only if v.get("video_id")}
                    for p_vid, p_info in PRE_ENRICHED_LOOKUP.items():
                        if p_vid and p_vid not in existing_ids and p_vid not in demo_ids:
                            existing_ids.add(p_vid)
                            real_only.append({
                                "video_id": p_vid,
                                "title": p_info.get("title", "Product Review"),
                                "amazon_url": p_info.get("amazon_url", ""),
                                "yt_description": p_info.get("yt_description", ""),
                                "transcript_summary": p_info.get("transcript_summary", ""),
                                "duration": p_info.get("duration", "1:45"),
                                "channel_id": p_info.get("channel_id", "ch1"),
                                "channel_name": p_info.get("channel_name", "KitchenGear"),
                                "yt_url": f"https://www.youtube.com/watch?v={p_vid}",
                            })
                    # 1. Instantly apply pre-enriched exact /dp/ASIN?tag=ziolek-20 & amzn.to links + full descriptions
                    for v in real_only:
                        pre = PRE_ENRICHED_LOOKUP.get(v.get("video_id", ""))
                        if pre:
                            if not v.get("amazon_url") and pre.get("amazon_url"):
                                v["amazon_url"] = pre["amazon_url"]
                            if not v.get("yt_description") and pre.get("yt_description"):
                                v["yt_description"] = pre["yt_description"]
                            if pre.get("transcript_summary"):
                                v["transcript_summary"] = pre["transcript_summary"]
                            if pre.get("channel_name"):
                                v["channel_name"] = pre["channel_name"]
                    # 2. Enrich any brand-new daily uploads via YouTube's official XML Atom feed + InnerTube JSON API
                    need_enrich = [
                        v for v in real_only
                        if not v.get("amazon_url") or not v.get("yt_description")
                    ]
                    if need_enrich:
                        xml_map = _fetch_xml_feed_lookup()
                        for v in need_enrich:
                            raw_xml_d = xml_map.get(v.get("video_id", ""))
                            if raw_xml_d:
                                amz = re.search(
                                    r"(https?://(?:www\.)?(?:amzn\.to|a\.co|amazon\.[a-z\.]+)/[^\s\)\"\]]+)",
                                    raw_xml_d,
                                    re.I,
                                )
                                if amz:
                                    v["amazon_url"] = amz.group(1)
                                v["yt_description"] = re.sub(r"\s{2,}", " ", raw_xml_d).strip()[:1400]
                                v["transcript_summary"] = _clean_summary_text(raw_xml_d, v.get("title", "Product Review"))
                        still_need = [
                            v for v in need_enrich
                            if not v.get("amazon_url") or not v.get("yt_description")
                        ][:300]
                        if still_need:
                            from concurrent.futures import ThreadPoolExecutor
                            with ThreadPoolExecutor(max_workers=24) as ex:
                                list(ex.map(_enrich_one_real_video, still_need))
                    # Save cleaned & enriched library back to disk
                    with open("videos_library.json", "w", encoding="utf-8") as wf:
                        json.dump(real_only, wf, indent=2, ensure_ascii=False)
                    enriched = []
                    for v in real_only:
                        title = v.get("title", "Product Review")
                        dur = v.get("duration", "2:00")
                        cid = v.get("channel_id", "ch1")
                        ch_name = ch_names.get(cid, v.get("channel_name", "KitchenGear"))
                        q_fb = requests.utils.quote(clean_title_for_ebay(title))
                        amz_u = v.get("amazon_url") or f"https://www.amazon.com/s?k={q_fb}&tag={CONFIG['amazon_tag']}"
                        desc = v.get("yt_description") or (
                            f"Product link: 🔗 Check it out: {amz_u} — Official Video Review & Specs for {title}."
                        )
                        if "http" not in desc:
                            desc = f"Product link: 🔗 Check it out: {amz_u} — {desc}"
                        trans = _clean_summary_text(v.get("transcript_summary") or desc, title)
                        enriched.append({
                            "video_id": v["video_id"],
                            "title": title,
                            "amazon_url": amz_u,
                            "duration": dur,
                            "channel_id": cid,
                            "channel_name": ch_name,
                            "yt_description": desc,
                            "transcript_summary": trans,
                            "yt_url": f"https://www.youtube.com/watch?v={v['video_id']}"
                        })
                    return enriched
        except Exception:
            pass
    return fallback_videos

